import {ROOF_KINDS,roofVisualKind} from './climbable-roofs.js';
export const canopyCells=p=>Array.from({length:4},(_,i)=>({x:p.x+i%2,y:p.y+Math.floor(i/2),z:3}));
export function canopyErrors(map,size=240){if(map.canopies===undefined)return [];if(!Array.isArray(map.canopies)||map.canopies.length>4096)return ['Invalid builder roof layer.'];const used=new Set();for(const p of map.canopies){if(!p||!Number.isInteger(p.x)||!Number.isInteger(p.y)||p.z!==3||!ROOF_KINDS.includes(roofVisualKind(p.kind||''))||(p.rotated!==undefined&&typeof p.rotated!=='boolean'))return ['Level 4 accepts roof modules only.'];for(const q of canopyCells(p)){const key=q.x+','+q.y;if(q.x<0||q.y<0||q.x>=size||q.y>=size||used.has(key))return ['Level 4 roof footprints overlap or leave the map.'];used.add(key);}}return [];}
export function canopyPresentation(map){if(!map.canopies?.length)return map;const roofFloor={};for(const p of map.canopies)for(const q of canopyCells(p))roofFloor[q.x+','+q.y]='floor';return {...map,props:[...(map.props||[]),...map.canopies],upper:[...map.upper,roofFloor],canopies:[]};}
export function previewCanopy(map,command,size){const {tool,start,options={}}=command,copy=structuredClone(map);copy.canopies||=[];const selected=copy.canopies.find(p=>canopyCells(p).some(q=>q.x===start.x&&q.y===start.y));if(['erase-prop','erase-tile','erase-roof'].includes(tool)){copy.canopies=copy.canopies.filter(p=>p!==selected);return {ok:true,map:copy,cells:selected?canopyCells(selected):[start],edges:[]};}if(!['roof-tile','prop'].includes(tool)||!ROOF_KINDS.includes(roofVisualKind(options.propKind||'')))return {ok:false,error:'Altitude 4 is for decorative roofs. Choose Roofs; characters remain on levels 1–3.'};const p={x:start.x,y:start.y,z:3,kind:options.propKind,rotated:!!options.rotated};copy.canopies.push(p);const errors=canopyErrors(copy,size);return {ok:!errors.length,error:errors[0],map:copy,cells:canopyCells(p),edges:[],orientation:options.rotated?[0,1]:[1,0]};}
